import json,pathlib
p=pathlib.Path(__file__).parent
schema='https://vega.github.io/schema/vega-lite/v5.json'
config={'view':{'stroke':None},'font':'DM Sans, sans-serif','axis':{'labelColor':'#d2dddf','titleColor':'#d2dddf','gridColor':'#304449','labelFontSize':11},'legend':{'labelColor':'#d2dddf','titleColor':'#d2dddf'}}
def save(n,s):(p/'specs'/f'{n}.json').write_text(json.dumps({'$schema':schema,'background':'transparent','config':config}|s,indent=2))
state={'url':'data/state-series.json'}
latest=[{'filter':'datum.year == 2025'}]
renew={'domain':[0,100],'range':['#274048','#80d5a8']}
geo='https://raw.githubusercontent.com/rowanhogan/australian-states/master/states.min.geojson'
mapdata={'url':geo,'format':{'type':'json','property':'features'}}
maptrans=[{'calculate':'datum.properties.STATE_NAME','as':'stateName'},{'lookup':'stateName','from':{'data':{'url':'data/state-2025.json'},'key':'state','fields':['share','total_gwh']}}]
mapbase={'width':'container','height':375,'projection':{'type':'mercator','center':[134,-27],'scale':510}}
save('03_regional_rank',{'width':'container','height':260,'data':state,'transform':latest,'mark':{'type':'bar','cornerRadiusEnd':5,'color':'#80d5a8'},'encoding':{'y':{'field':'state','type':'nominal','sort':'-x','title':None},'x':{'field':'share','type':'quantitative','scale':{'domain':[0,100]},'title':'Renewables (% of generation)'},'tooltip':[{'field':'state'},{'field':'share','title':'Renewables (%)','format':'.1f'}]}})
save('05_map_renewable',mapbase|{'data':mapdata,'transform':maptrans,'mark':{'type':'geoshape','stroke':'#152e34','strokeWidth':1.5},'encoding':{'color':{'field':'share','type':'quantitative','scale':renew,'title':'Renewables (%)'},'tooltip':[{'field':'stateName','title':'State'},{'field':'share','title':'Renewables (%)','format':'.1f'}]}})
save('06_map_select',mapbase|{'data':mapdata,'transform':maptrans,'mark':{'type':'geoshape','stroke':'#152e34','strokeWidth':1.5},'encoding':{'color':{'condition':{'test':'datum.share >= 50','value':'#80d5a8'},'value':'#34454a'},'tooltip':[{'field':'stateName','title':'State'},{'field':'share','title':'Renewables (%)','format':'.1f'}]}})
save('07_map_symbols',mapbase|{'layer':[{'data':mapdata,'mark':{'type':'geoshape','fill':'#294045','stroke':'#718582','strokeWidth':1}},{'data':state,'transform':latest,'mark':{'type':'circle','color':'#edb66d','opacity':.8,'stroke':'#fff3dc','strokeWidth':.6},'encoding':{'longitude':{'field':'lon'},'latitude':{'field':'lat'},'size':{'field':'total_gwh','type':'quantitative','scale':{'range':[70,2200]},'title':'Generation (GWh)'},'tooltip':[{'field':'state'},{'field':'total_gwh','title':'Generation (GWh)','format':',.0f'}]}}]})
save('08_trajectories',{'width':'container','height':300,'data':state,'mark':{'type':'line','point':{'size':30},'strokeWidth':2},'encoding':{'x':{'field':'year','type':'ordinal','title':None},'y':{'field':'share','type':'quantitative','scale':{'domain':[0,100]},'title':'Renewable share (%)'},'color':{'field':'region','type':'nominal','title':'State'},'tooltip':[{'field':'state'},{'field':'year'},{'field':'share','format':'.1f','title':'Renewable share (%)'}]}})
save('09_heatmap',{'width':'container','height':270,'data':state,'mark':{'type':'rect','stroke':'#13272c','strokeWidth':1},'encoding':{'x':{'field':'year','type':'ordinal','title':None},'y':{'field':'region','type':'nominal','title':None,'sort':['TAS','SA','VIC','NSW','QLD','WA','NT']},'color':{'field':'share','type':'quantitative','scale':renew,'title':'Renewables (%)'},'tooltip':[{'field':'state'},{'field':'year'},{'field':'share','title':'Renewables (%)','format':'.1f'}]}})
save('10_change',{'width':'container','height':285,'data':state,'transform':[{'filter':'datum.year == 2015 || datum.year == 2025'}],'mark':{'type':'line','point':{'filled':True,'size':85},'strokeWidth':3},'encoding':{'x':{'field':'year','type':'ordinal','title':None},'y':{'field':'share','type':'quantitative','scale':{'domain':[0,100]},'title':'Renewable share (%)'},'color':{'field':'region','type':'nominal','title':'State'},'tooltip':[{'field':'state'},{'field':'year'},{'field':'share','title':'Renewables (%)','format':'.1f'}]}})
save('11_absolute',{'width':'container','height':270,'data':state,'transform':latest,'mark':{'type':'bar','cornerRadiusEnd':3,'color':'#edb66d'},'encoding':{'y':{'field':'region','type':'nominal','sort':'-x','title':None},'x':{'field':'total_gwh','type':'quantitative','title':'Generation (GWh)'},'tooltip':[{'field':'state'},{'field':'total_gwh','title':'Generation (GWh)','format':',.0f'}]}})
save('12_fuel_state',{'width':'container','height':270,'data':{'url':'data/generation-cy.json'},'transform':[{'filter':'datum.year == 2025 && datum.region != "AUS" && (datum.fuel == "Wind" || datum.fuel == "Hydro" || datum.fuel == "Large-scale solar PV" || datum.fuel == "Small-scale solar PV")'},{'calculate':'datum.gwh / 1000','as':'twh'}],'mark':'rect','encoding':{'x':{'field':'region','type':'nominal','title':None},'y':{'field':'fuel','type':'nominal','title':None},'color':{'field':'twh','type':'quantitative','scale':{'scheme':'greenblue'},'title':'TWh'},'tooltip':[{'field':'region'},{'field':'fuel'},{'field':'twh','title':'TWh','format':'.2f'}]}})
save('13_station_dots',mapbase|{'layer':[{'data':mapdata,'mark':{'type':'geoshape','fill':'#294045','stroke':'#718582','strokeWidth':1}},{'data':{'url':'data/major-stations-100mw.json'},'mark':{'type':'circle','size':35,'opacity':.78,'stroke':'#071a20','strokeWidth':.5},'encoding':{'longitude':{'field':'longitude','type':'quantitative'},'latitude':{'field':'latitude','type':'quantitative'},'color':{'field':'fuel','type':'nominal','title':'Primary fuel','scale':{'domain':['Fossil','Wind','Solar','Water','Biomass Or Waste','Wind/solar'],'range':['#da8265','#7ed4a7','#f6be77','#78bce0','#ad95bf','#d1e785']}},'tooltip':[{'field':'name','title':'Station'},{'field':'fuel','title':'Primary fuel'},{'field':'capacity_mw','title':'Capacity (MW)','format':',.0f'},{'field':'state','title':'State'}]}}]})

save('14_stream',{'width':'container','height':340,'data':{'url':'data/national-stream-2015-2025.json'},'mark':{'type':'area','interpolate':'monotone','opacity':.94},'encoding':{'x':{'field':'year','type':'quantitative','scale':{'domain':[2015,2025]},'axis':{'format':'d','tickMinStep':1},'title':None},'y':{'field':'twh','type':'quantitative','stack':'center','title':'Electricity generation (TWh, centred)'},'color':{'field':'source','type':'nominal','sort':['Black coal','Brown coal','Gas','Oil','Biomass','Hydro','Wind','Solar'],'scale':{'domain':['Black coal','Brown coal','Gas','Oil','Biomass','Hydro','Wind','Solar'],'range':['#bf6b52','#de9377','#f3bb81','#c7ab9c','#b4bd7a','#75b6dc','#6fc9ac','#e6d767']},'title':'Generation source'},'order':{'field':'order','type':'quantitative'},'tooltip':[{'field':'year','type':'quantitative','format':'d'},{'field':'source'},{'field':'twh','title':'Generation (TWh)','format':'.1f'}]}})
